window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[129]={"id":"129","numero":129,"titre":"Arthrose","objectifs":[{"id":"129-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition générale de l’arthrose, les principales localisations","contenu":"<p>L'<span class=\"kw-def\">arthrose</span> est une maladie articulaire caractérisée par une\n        <strong><span class=\"kw-def\">destruction du cartilage</span></strong> qui s'étend secondairement à\n        <strong>toutes <span class=\"kw-clinique\">les</span> structures de l'articulation</strong>. Elle touche en premier lieu le\n        <span class=\"kw-def\">cartilage articulaire</span>, mais aussi la <span class=\"kw-def\">membrane synoviale</span>\n        et l'<span class=\"kw-def\">os sous-chondral</span>. C'est la <strong><span class=\"kw-def\">maladie rhumatismale la plus fréquente</span></strong>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Localisations préférentielles</strong></td>\n            <td><span class=\"kw-clinique\">rachis</span> et <span class=\"kw-clinique\">genoux</span> &gt;\n              <span class=\"kw-clinique\">mains</span> &gt; <span class=\"kw-clinique\">hanches</span></td></tr>\n          <tr><td><strong>Présentation</strong></td>\n            <td>Longtemps <span class=\"kw-clinique\">asymptomatique</span>, peut devenir <span class=\"kw-clinique\">symptomatique</span> :\n              <span class=\"kw-clinique\">douleur mécanique</span>, <span class=\"kw-clinique\">gêne fonctionnelle</span></td></tr>\n          <tr><td><strong>Conséquences générales</strong></td>\n            <td><span class=\"kw-alerte\">sédentarité</span> (surtout chez le gonarthrosique) →\n              <span class=\"kw-alerte\">surmortalité cardiovasculaire</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Ne jamais considérer l'arthrose comme un phénomène « normal » du sujet âgé : c'est une maladie, à dépister et à prendre en charge.</div>","frequence":0},{"id":"129-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l’arthrose","contenu":"<ul>\n        <li>L'<span class=\"kw-def\">arthrose</span> touche <span class=\"kw-chiffre\">≈ 10 %</span> de la\n          <span class=\"kw-clinique\">population générale</span>, et jusqu'à\n          <span class=\"kw-chiffre\">50 %</span> des sujets de <span class=\"kw-chiffre\">&gt; 60 ans</span>\n          (<span class=\"kw-chiffre\">un adulte sur deux</span> après <span class=\"kw-chiffre\">60 ans</span>).</li>\n        <li><span class=\"kw-chiffre\">9 à 10 millions</span> de patients en France.</li>\n        <li><strong><span class=\"kw-def\">Maladie rhumatismale la plus fréquente</span>.</strong></li>\n        <li>Coût médico-économique considérable, estimé à <span class=\"kw-chiffre\">≈ 1 milliard €</span> en France,\n          du fait de sa forte <span class=\"kw-bio\">prévalence</span> et de son\n          <span class=\"kw-clinique\">retentissement fonctionnel</span>.</li>\n      </ul>","frequence":0},{"id":"129-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des localisations arthrosiques","contenu":"<p>La <strong>localisation la plus fréquente aux membres inférieurs est le <span class=\"kw-clinique\">genou</span></strong>.\n        L'<span class=\"kw-def\">incidence</span> annuelle de l'arthrose <span class=\"kw-clinique\">symptomatique</span> varie selon la localisation :</p>\n      <table >\n        <thead><tr><th>Localisation symptomatique</th><th>Incidence annuelle</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Gonarthrose</span></strong> (genou)</td><td><span class=\"kw-chiffre\">240 / 100 000</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Arthrose digitale</span></strong> (mains)</td><td><span class=\"kw-chiffre\">100 / 100 000</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Coxarthrose</span></strong> (hanche)</td><td><span class=\"kw-chiffre\">80 / 100 000</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><span class=\"kw-def\">Prévalence</span> globale par fréquence décroissante : <span class=\"kw-clinique\">rachis</span> et\n          <span class=\"kw-clinique\">genou</span> &gt; <span class=\"kw-clinique\">mains</span> &gt; <span class=\"kw-clinique\">hanche</span>.</li>\n        <li>Prédominance <span class=\"kw-etio\">féminine</span>, surtout <span class=\"kw-etio\">après la ménopause</span>.</li>\n      </ul>","frequence":0},{"id":"129-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l’arthrose","contenu":"<p>L'<span class=\"kw-def\">articulation synoviale</span> (touchée par l'arthrose) comporte 4 tissus :</p>\n      <ul>\n        <li><strong>Capsule</strong> : entoure l'articulation.</li>\n        <li><strong>Membrane synoviale</strong> : sécrète le <span class=\"kw-bio\">liquide synovial</span>\n          (lubrifiant, normalement en très faible quantité).</li>\n        <li><strong>Os sous-chondral</strong> : supporte le cartilage et assure le passage des nutriments.</li>\n        <li><strong>Cartilage articulaire</strong> : tissu <strong><span class=\"kw-def\">non vascularisé</span></strong> et\n          <strong><span class=\"kw-def\">non innervé</span></strong>, fait d'un seul type cellulaire — <span class=\"kw-clinique\">les</span>\n          <span class=\"kw-def\">chondrocytes</span> ; matrice = <span class=\"kw-chiffre\">eau &gt; 80 %</span> +\n          réseau de <span class=\"kw-def\">collagène</span> et de <span class=\"kw-def\">protéoglycanes</span>\n          (hydrophiles), rôle = <strong>absorber les contraintes mécaniques</strong>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Stress</strong></td>\n            <td>Origine <span class=\"kw-etio\">mécanique</span> (excès de contrainte), <span class=\"kw-etio\">inflammatoire</span>\n              ou <span class=\"kw-etio\">métabolique</span></td></tr>\n          <tr><td><strong>2. Inflammation locale de bas <span class=\"kw-def\">grade</span></strong></td>\n            <td>Production de <span class=\"kw-bio\">cytokines</span> → sécrétion d'enzymes protéolytiques\n              (<span class=\"kw-bio\">métalloprotéases</span>) qui digèrent la matrice du cartilage</td></tr>\n          <tr><td><strong>3. Réponse au stress</strong></td>\n            <td>Dégradation du cartilage ; inflammation de la membrane synoviale (débris cartilagineux) ;\n              remodelage de l'os sous-chondral → <span class=\"kw-imagerie\">géodes</span>,\n              <span class=\"kw-imagerie\">sclérose</span>, <span class=\"kw-imagerie\">ostéophytes</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trois stades évolutifs</strong> de la dégradation cartilagineuse :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-clinique\">Lésion</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Initial (<span class=\"kw-clinique\">œdème</span>)</strong></td>\n            <td>Hyperhydratation (surproduction de protéoglycanes) → <span class=\"kw-clinique\">ramollissement</span> ;\n              néocollagène de type I (moindre qualité)</td></tr>\n          <tr><td><strong>Intermédiaire</strong></td>\n            <td>Hyperactivité catabolique des chondrocytes → <span class=\"kw-clinique\">fissures superficielles</span> +\n              relargage d'enzymes et de cytokines</td></tr>\n          <tr><td><strong>Final</strong></td>\n            <td>Mise à nu de l'<span class=\"kw-imagerie\">os sous-chondral</span> → réaction osseuse :\n              <span class=\"kw-imagerie\">ostéophytes</span>, <span class=\"kw-imagerie\">condensation</span>,\n              <span class=\"kw-imagerie\">géodes</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/129/physiopath-arthrose-catabolisme.png\" alt=\"Schéma physiopathologique de l'arthrose : déséquilibre anabolisme/catabolisme du chondrocyte, inflammation articulaire et surexpression des enzymes protéolytiques\" loading=\"lazy\">\n        <figcaption>Déséquilibre <strong>anabolisme / catabolisme</strong> du <span class=\"kw-def\">chondrocyte</span> : sous l'effet du stress, le catabolisme l'emporte (<span class=\"kw-bio\">métalloprotéases</span>, agrécanases) → <span class=\"kw-etio\">inflammation articulaire</span> et destruction du cartilage. Source : fiche source EDN item 129 — Arthrose (COFER).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">La <span class=\"kw-clinique\">douleur</span> arthrosique est complexe : le cartilage n'étant pas innervé, elle provient de l'<span class=\"kw-imagerie\">os sous-chondral</span>, de la capsule mise en tension, de la membrane synoviale, et de mécanismes de <span class=\"kw-def\">sensibilisation centrale</span>.</div>","frequence":0},{"id":"129-5","rang":"A","rubrique":"Etiologies","titre":"Connaître les principaux facteurs de risque de l’arthrose","contenu":"<p><span class=\"kw-def\">Facteurs de risque</span> de l'<strong>arthrose primitive</strong>, classés en trois familles :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Non modifiables</strong></td>\n            <td><span class=\"kw-etio\">Âge</span> : rare avant <span class=\"kw-chiffre\">&lt; 40 ans</span>, <span class=\"kw-def\">incidence</span> forte après\n              <span class=\"kw-chiffre\">&gt; 60 ans</span><br>\n              <span class=\"kw-etio\">Sexe féminin</span>, surtout après la <span class=\"kw-etio\">ménopause</span><br>\n              <span class=\"kw-etio\">Hérédité</span> (polymorphismes de susceptibilité) → localisation la plus concernée =\n              <strong>arthrose digitale</strong></td></tr>\n          <tr><td><strong>Métaboliques</strong></td>\n            <td><span class=\"kw-etio\">Surpoids / obésité</span> : favorise <span class=\"kw-clinique\">les</span> articulations portantes\n              (<span class=\"kw-clinique\">genou</span>, <span class=\"kw-clinique\">rachis</span>, <span class=\"kw-clinique\">hanche</span>)\n              et non portantes (<span class=\"kw-clinique\">digitale</span>)<br>\n              <span class=\"kw-etio\">Syndrome métabolique</span> (<span class=\"kw-etio\">HTA</span>, DT2/insulinorésistance, dyslipidémie, obésité)</td></tr>\n          <tr><td><strong>Excès de contrainte mécanique</strong></td>\n            <td><span class=\"kw-etio\">Port de charges lourdes</span>, <span class=\"kw-etio\">microtraumatismes répétés</span><br>\n              ATCD de lésions <span class=\"kw-etio\">ménisco-ligamentaires</span> (croisés, ménisques) ou de\n              <span class=\"kw-etio\">fractures articulaires</span><br>\n              Troubles d'architecture : <strong>genou</strong> → <span class=\"kw-etio\">genu varum</span> /\n              <span class=\"kw-etio\">genu valgum</span> ; <strong>hanche</strong> → <span class=\"kw-etio\">dysplasie</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/129/genu-valgum-vs-varum.png\" alt=\"Comparaison genu valgum (genoux en dedans, knock-knee) versus genu varum (genoux écartés, bow-legged), avec moyen mnémotechnique GUM/RUM\" loading=\"lazy\">\n        <figcaption><span class=\"kw-etio\">Genu valgum</span> (« knock-knee », genoux en dedans) <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">genu varum</span> (« bow-legged », genoux écartés) — troubles de la statique qui surchargent un compartiment du genou. Mnémo : <strong>vaL</strong>gum / <strong>vaR</strong>um. Source : fiche source EDN item 129 — Gonarthrose (COFER).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">Trois <strong>types d'arthrose primitive</strong>, pouvant se combiner : liée au <span class=\"kw-etio\">vieillissement</span>, <span class=\"kw-etio\">métabolique</span> (<span class=\"kw-etio\">obésité</span> / syndrome métabolique), <span class=\"kw-etio\">post-traumatique</span>.</div>","frequence":0},{"id":"129-6","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des arthroses secondaires et génétiques","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>arthroses secondaires</strong> surviennent sur une <span class=\"kw-etio\">arthropathie destructrice\n        préexistante</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Arthrites septiques</span></li>\n        <li><span class=\"kw-etio\">Arthrites microcristallines</span> (<span class=\"kw-etio\">goutte</span>,\n          <span class=\"kw-etio\">chondrocalcinose</span>)</li>\n        <li>Rhumatismes inflammatoires destructeurs : <span class=\"kw-etio\">polyarthrite rhumatoïde</span>,\n          <span class=\"kw-etio\">spondyloarthrite</span></li>\n        <li>Anomalies métaboliques : <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">microcristaux</span>,\n          <span class=\"kw-etio\">hémochromatose</span></li>\n      </ul>\n      <p><strong>Composante <span class=\"kw-etio\">génétique</span></strong> : familles à <span class=\"kw-def\">prévalence</span> très supérieure à la population générale ;\n        <span class=\"kw-etio\">hérédité</span> et <span class=\"kw-etio\">polymorphismes de susceptibilité</span> du cartilage ;\n        localisation la plus <span class=\"kw-etio\">héréditaire</span> = <strong><span class=\"kw-clinique\">arthrose digitale</span></strong>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span> · 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span> · 198 — Arthropathie microcristalline · 156 — Infection ostéo-articulaire</em></p>","frequence":0},{"id":"129-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une coxarthrose, une gonarthrose ou une arthrose digitale","contenu":"<p>Diagnostic essentiellement <strong>clinique + radiographique</strong>. Point commun :\n        <span class=\"kw-clinique\">douleur d'horaire mécanique</span> (à l'effort, calmée par le repos, ne réveille pas la nuit\n        sauf changement de position), <span class=\"kw-clinique\">dérouillage matinal &lt; 15 min</span>, et\n        <strong>absence de <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span></strong>.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Sémiologie clinique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coxarthrose</strong></td>\n            <td><span class=\"kw-clinique\">Douleur inguino-crurale</span> (pli de l'aine), pouvant irradier face antérieure de cuisse<br>\n              <span class=\"kw-clinique\">Boiterie d'esquive</span> ; <span class=\"kw-clinique\">flessum</span> + limitation de la\n              <span class=\"kw-clinique\">rotation médiale</span> et de l'extension<br>\n              <span class=\"kw-clinique\">Amyotrophie du quadriceps</span></td></tr>\n          <tr><td><strong>Gonarthrose fémoro-tibiale</strong></td>\n            <td><span class=\"kw-clinique\">Douleur mécanique</span> à la <span class=\"kw-clinique\">montée/descente des escaliers</span>,\n              globale ou latéralisée<br>\n              <span class=\"kw-clinique\">Craquements</span>, <span class=\"kw-clinique\">choc rotulien</span> (épanchement),\n              <span class=\"kw-clinique\">kyste poplité</span> possible</td></tr>\n          <tr><td><strong>Gonarthrose fémoro-patellaire</strong></td>\n            <td><span class=\"kw-clinique\">Douleur antérieure du genou</span> (descente d'escalier, agenouillement,\n              <span class=\"kw-clinique\">signe du cinéma</span>)<br>\n              <span class=\"kw-clinique\">Syndrome rotulien</span> : <span class=\"kw-clinique\">manœuvre du rabot</span>,\n              <span class=\"kw-clinique\">signe de Zohlen</span></td></tr>\n          <tr><td><strong>Arthrose digitale</strong></td>\n            <td>Fréquence : <strong>IPD</strong> &gt; <strong>rhizarthrose</strong> (base du pouce) &gt; <strong><span class=\"kw-ttt\">IPP</span></strong><br>\n              <span class=\"kw-clinique\">Nodules d'Heberden</span> (IPD, P3) et <span class=\"kw-clinique\">nodules de Bouchard</span> (<span class=\"kw-ttt\">IPP</span>, P2)<br>\n              <span class=\"kw-clinique\">Rhizarthrose</span> : douleur de la racine du pouce, gêne à la pince</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Critères <span class=\"kw-alerte\">ACR</span> de l'<strong>arthrose digitale</strong> : <span class=\"kw-clinique\">douleur/raideur digitale</span> + 3/4 critères (élargissement <span class=\"kw-chiffre\">≥ 2</span> des 10 articulations cibles, ≥ 2 IPD, déformation ≥ 1 articulation cible, &lt; 3 MCP gonflées). Si déformations typiques → <strong>diagnostic purement clinique</strong>, sans <span class=\"kw-imagerie\">radiographie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 200 — Douleur/épanchement articulaire - Arthrite récente · 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span> · 198 — Arthropathie microcristalline</em></p>","frequence":3},{"id":"129-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels des principales localisations arthrosiques : coxarthrose, gonarthrose, arthrose digitale","contenu":"<table >\n        <thead><tr><th>Localisation</th><th>Diagnostics différentiels</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coxarthrose</strong></td>\n            <td><span class=\"kw-etio\">Cruralgie</span> (déficit neurologique, réflexe rotulien aboli)<br>\n              <span class=\"kw-etio\">Ostéonécrose</span> de la tête fémorale (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-imagerie\">IRM</span>)<br>\n              <span class=\"kw-etio\">Fissure ostéoporotique</span> du bassin ; <span class=\"kw-etio\">SDRC</span> de hanche (<span class=\"kw-ci\">grossesse</span>)<br>\n              <span class=\"kw-etio\">Tendinopathie</span> du moyen fessier / du droit antérieur ;\n              <span class=\"kw-etio\">névralgie fémoro-cutanée</span></td></tr>\n          <tr><td><strong>Gonarthrose</strong></td>\n            <td>Douleur <span class=\"kw-etio\">coxofémorale projetée</span> ; <span class=\"kw-etio\">radiculalgie L3-L4</span><br>\n              <span class=\"kw-etio\">Lésion méniscale</span> (sujet jeune, traumatisme, blocages)<br>\n              <span class=\"kw-etio\">Arthropathie microcristalline</span> ; <span class=\"kw-etio\">ostéonécrose</span> /\n              <span class=\"kw-etio\">fissure d'un condyle</span> ; <span class=\"kw-alerte\">phlébite</span><br>\n              <span class=\"kw-etio\">Tendinopathies</span> (rotulienne, patte d'oie)</td></tr>\n          <tr><td><strong>Arthrose digitale</strong></td>\n            <td><span class=\"kw-etio\">Rhumatisme psoriasique</span> (atteinte IPD, mais érosions/élargissement)<br>\n              <span class=\"kw-etio\">Polyarthrite rhumatoïde</span> ; <span class=\"kw-etio\">goutte</span>\n              (ne pas confondre <strong>tophus</strong> et nodosités d'Heberden/Bouchard)<br>\n              <span class=\"kw-etio\">Chondrocalcinose</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"129-9","rang":"A","rubrique":"Examens complémentaires","titre":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","contenu":"<p>La <strong><span class=\"kw-imagerie\">radiographie standard</span></strong> est l'examen clé : elle\n        <strong>suffit au diagnostic</strong> dans la grande majorité des cas. <strong>Aucun examen <span class=\"kw-ttt\">biologique</span></strong>\n        n'est nécessaire ; aucune <span class=\"kw-imagerie\">imagerie en coupe</span> en <span class=\"kw-chiffre\">première intention</span>.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Clichés indispensables</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Coxarthrose</span></strong></td>\n            <td><span class=\"kw-imagerie\">Bassin debout de face</span> (membres en <span class=\"kw-imagerie\">rotation interne 20°</span>) +\n              <span class=\"kw-imagerie\">faux profil de Lequesne</span> de chaque hanche</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Gonarthrose</span></strong></td>\n            <td><span class=\"kw-imagerie\">Face en appui bipodal</span> (genou en extension) +\n              <span class=\"kw-imagerie\">profil</span> + <span class=\"kw-imagerie\">défilé fémoro-patellaire à 30°</span> +\n              <span class=\"kw-imagerie\">incidence en schuss</span> (face, charge, 30° de flexion)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Arthrose digitale</span></strong></td>\n            <td><span class=\"kw-imagerie\">Radiographie des mains de face</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li>Autres imageries réservées au <strong>doute diagnostique</strong> ou aux DD :\n          <span class=\"kw-imagerie\">échographie</span> (épanchement, guidage de <span class=\"kw-ttt\">ponction</span>),\n          <span class=\"kw-imagerie\">IRM</span>/<span class=\"kw-imagerie\">arthroscanner</span> (ostéonécrose, fissure, <span class=\"kw-clinique\">lésion</span> du labrum).</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Dissociation anatomo-clinique</strong> : l'importance des lésions radiologiques n'est <strong>pas corrélée</strong> à la douleur ni au retentissement fonctionnel.</div>","frequence":1},{"id":"129-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie générale en radio de l’arthrose : coxarthrose gonarthrose, arthrose digitale","contenu":"<p>Quatre <strong>signes cardinaux radiologiques</strong> de l'arthrose (ne sont pas tous obl<span class=\"kw-chiffre\">iga</span>toirement présents) :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Pincement de l'interligne</span></strong></td>\n            <td><span class=\"kw-imagerie\">Localisé</span> (à la zone d'hyperpression), apprécié de façon comparative —\n              ≠ <span class=\"kw-imagerie\">pincement global</span> des arthrites inflammatoires</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Ostéophytose marginale</span></strong></td>\n            <td><span class=\"kw-imagerie\">Becs osseux</span> aux marges articulaires —\n              <strong>signe le plus spécifique de l'arthrose</strong></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Géodes (lacunes) sous-chondrales</span></strong></td>\n            <td><span class=\"kw-imagerie\">Lacunes cerclées</span> en regard du pincement maximal (zone d'hyperpression)</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Ostéosclérose / condensation sous-chondrale</span></strong></td>\n            <td><span class=\"kw-imagerie\">Densification osseuse</span> aux zones d'hyperpression</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Signes <strong>négatifs</strong> attendus : <span class=\"kw-alerte\">pas de déminéralisation</span>, <span class=\"kw-alerte\">pas d'érosion</span> ni de destruction articulaire (sauf forme digitale érosive) — ce qui distingue l'arthrose des rhumatismes inflammatoires.</div>","frequence":1},{"id":"129-11","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de coxarthrose","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/129/radio-coxarthrose-normale-vs-arthrosique.png\" alt=\"Radiographie comparative de hanche : hanche normale (interligne conservé) versus hanche arthrosique (pincement polaire supérieur, ostéophytes, géodes)\" loading=\"lazy\">\n        <figcaption><strong>Hanche normale</strong> (interligne articulaire conservé) <span class=\"kw-bio\">vs</span> <strong>hanche arthrosique</strong> : <span class=\"kw-imagerie\">pincement articulaire polaire supérieur</span>, <span class=\"kw-imagerie\">ostéophytes</span> et <span class=\"kw-imagerie\">géodes</span>. Source : fiche source EDN item 129 — Coxarthrose (COFER).</figcaption>\n      </figure>\n      <p>Sur le <span class=\"kw-imagerie\">bassin de face</span> + <span class=\"kw-imagerie\">faux profil de Lequesne</span>, signes d'une <span class=\"kw-def\">coxarthrose</span> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Pincement supéro-latéral</span> de l'interligne le plus souvent (de face) ; pincement\n          <span class=\"kw-imagerie\">antérieur</span> sur le profil — le cliché de profil peut révéler un pincement non vu de face.</li>\n        <li><span class=\"kw-imagerie\">Ostéosclérose condensante</span> au pôle supérieur de la tête fémorale et au toit du cotyle.</li>\n        <li><span class=\"kw-imagerie\">Ostéophytose marginale</span> (avant-toit, péri-céphalique, péri-fovéale, « en hamac » sous le col).</li>\n        <li><span class=\"kw-imagerie\">Géodes</span> en zone d'hyperpression ; aux formes évoluées, <span class=\"kw-imagerie\">perte de sphéricité</span> de la tête fémorale.</li>\n      </ul>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/osteoarthritis-of-the-hip","label":"Radiopaedia : Osteoarthritis of the hip"}]},{"id":"129-12","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de gonarthrose","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/129/radio-gonarthrose-schuss.png\" alt=\"Radiographie du genou en incidence de schuss (cliché de référence) — repères anatomiques du compartiment fémoro-tibial\" loading=\"lazy\">\n        <figcaption>Genou de face en <span class=\"kw-imagerie\">incidence de schuss</span> (cliché de référence) : vue en charge à 30° de flexion explorant le <strong>compartiment postérieur</strong>, le plus précocement atteint. Source : fiche source EDN item 129 — Gonarthrose (COFER).</figcaption>\n      </figure>\n      <p>Signes radiologiques d'une <span class=\"kw-def\">gonarthrose</span> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Pincement localisé</span> de l'interligne (un seul\n          <span class=\"kw-imagerie\">compartiment fémoro-tibial</span>, le plus souvent <span class=\"kw-imagerie\">médial</span>).</li>\n        <li><span class=\"kw-imagerie\">Ostéophytose marginale</span> (interne et externe) et des <span class=\"kw-imagerie\">épines tibiales</span>\n          (visibles en <span class=\"kw-imagerie\">schuss</span>).</li>\n        <li><span class=\"kw-imagerie\">Géodes</span> et <span class=\"kw-imagerie\">ostéosclérose</span> sous-chondrales.</li>\n        <li>L'<span class=\"kw-imagerie\">incidence de schuss</span> révèle un pincement du\n          <span class=\"kw-imagerie\">compartiment postérieur</span> non vu sur le cliché en extension.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Pas de corrélation entre l'importance des lésions radiologiques et la clinique.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/osteoarthritis-of-the-knee","label":"Radiopaedia : Osteoarthritis of the knee"}]},{"id":"129-13","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie d’arthrose des articulations interphalangiennes distales","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/129/radio-arthrose-digitale-main.png\" alt=\"Radiographie de la main avec arthrose interphalangienne distale et corrélat clinique : nodosités d'Heberden des doigts\" loading=\"lazy\">\n        <figcaption>Arthrose digitale : <span class=\"kw-imagerie\">atteinte des interphalangiennes distales (IPD)</span> à la <span class=\"kw-imagerie\">radiographie</span> de la main, avec son corrélat clinique — <span class=\"kw-clinique\">nodosités d'Heberden</span>. Source : fiche source EDN item 129 — Arthrose digitale (COFER).</figcaption>\n      </figure>\n      <p>Sur la <span class=\"kw-imagerie\">radiographie des mains de face</span> (atteinte des\n        <strong><span class=\"kw-clinique\">IPD</span></strong>) :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Pincement de l'interligne</span> souvent <span class=\"kw-imagerie\">global</span> (petites articulations).</li>\n        <li><span class=\"kw-imagerie\">Ostéophytose latérale / marginale</span>, parfois très exubérante, responsable des\n          <span class=\"kw-clinique\">nodosités</span>.</li>\n        <li><span class=\"kw-imagerie\">Géodes</span> et <span class=\"kw-imagerie\">ostéocondensation</span> sous-chondrales.</li>\n        <li>Signes <strong>négatifs</strong> : <span class=\"kw-alerte\">pas d'érosion</span> ni de destruction (sauf forme érosive).</li>\n      </ul>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/osteoarthritis-of-the-hand","label":"Radiopaedia : Osteoarthritis of the hand"}]},{"id":"129-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie particulière en radiographie de l’arthrose en fonction des différentes localisations","contenu":"<table >\n        <thead><tr><th>Localisation</th><th>Particularités radiographiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Coxarthrose</span></strong></td>\n            <td>Pincement <span class=\"kw-imagerie\">supéro-latéral</span> (face) le plus souvent ; pincement\n              <span class=\"kw-imagerie\">antérieur</span> (profil) ; intérêt du faux profil quand la face est normale</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Gonarthrose fémoro-tibiale</span></strong></td>\n            <td>Pincement <span class=\"kw-imagerie\">uni-compartimental</span> (médial ++) ; ostéophytose des\n              <span class=\"kw-imagerie\">épines tibiales</span> ; <span class=\"kw-imagerie\">schuss</span> = <span class=\"kw-imagerie\">compartiment postérieur</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Gonarthrose fémoro-patellaire</span></strong></td>\n            <td>Incidences <span class=\"kw-imagerie\">axiales à 30°/60°</span> : pincement <span class=\"kw-imagerie\">externe</span>,\n              <span class=\"kw-imagerie\">ostéophytose patellaire/trochléenne externe</span>, rotule translatée en dehors ;\n              dysplasie si <span class=\"kw-chiffre\">angle trochléen &gt; 140°</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Arthrose digitale</span></strong></td>\n            <td>Pincement <span class=\"kw-imagerie\">global</span>, ostéophytose exubérante ; forme <strong>érosive</strong> =\n              aspect en <span class=\"kw-imagerie\">« aile de mouette »</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"129-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître diagnostics différentiels d’arthrose","contenu":"<p>Distinguer l'arthrose d'un <strong>rhumatisme <span class=\"kw-etio\">inflammatoire</span></strong> ou d'une\n        <strong>arthropathie destructrice</strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Arthrose</th><th>Rhumatisme inflammatoire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Horaire de la douleur</strong></td>\n            <td><span class=\"kw-clinique\">Mécanique</span> (effort, calmée par le repos)</td>\n            <td><span class=\"kw-alerte\">Inflammatoire</span> (<span class=\"kw-clinique\">réveils nocturnes</span>, <span class=\"kw-clinique\">dérouillage long</span>)</td></tr>\n          <tr><td><strong>Biologie</strong></td>\n            <td><span class=\"kw-bio\">Pas de syndrome inflammatoire</span></td>\n            <td><span class=\"kw-bio\">Syndrome inflammatoire</span> possible</td></tr>\n          <tr><td><strong>Pincement radiologique</strong></td>\n            <td><span class=\"kw-imagerie\">Localisé</span></td>\n            <td><span class=\"kw-imagerie\">Global</span></td></tr>\n          <tr><td><strong>Os</strong></td>\n            <td><span class=\"kw-imagerie\">Ostéophytose</span> (spécifique), <span class=\"kw-imagerie\">pas d'érosion</span></td>\n            <td><span class=\"kw-imagerie\">Érosions</span>, <span class=\"kw-imagerie\">déminéralisation</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li>Éliminer une <span class=\"kw-etio\">arthrite microcristalline</span> (goutte, chondrocalcinose) et une\n          <span class=\"kw-alerte\">arthrite septique</span> (<span class=\"kw-ttt\">ponction</span> au moindre doute).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span> · 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span> · 198 — Arthropathie microcristalline · 156 — Infection ostéo-articulaire</em></p>","frequence":1},{"id":"129-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Savoir évaluer une arthrose","contenu":"<p>Évaluation surtout <strong>fonctionnelle</strong> (la <span class=\"kw-imagerie\">radiographie</span> n'est pas corrélée aux symptômes) :</p>\n      <table >\n        <thead><tr><th>Outil</th><th>Usage</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Indice de Lequesne</span></strong></td>\n            <td><span class=\"kw-clinique\">Hanche</span> et <span class=\"kw-clinique\">genou</span> — un seuil\n              <span class=\"kw-chiffre\">≥ 10–12</span> fait discuter une prothèse</td></tr>\n          <tr><td><strong><span class=\"kw-def\">WOMAC</span>, <span class=\"kw-def\">KOOS</span></strong></td>\n            <td>Indices algofonctionnels du <span class=\"kw-clinique\">genou</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Dreiser</span>, <span class=\"kw-def\">Cochin</span></strong></td>\n            <td>Indices fonctionnels de la <span class=\"kw-clinique\">main</span> (arthrose digitale)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">EVA</span>, <span class=\"kw-clinique\">périmètre de marche</span></strong></td>\n            <td><span class=\"kw-clinique\">Douleur</span> et <span class=\"kw-clinique\">retentissement à la marche</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><span class=\"kw-def\">Suivi</span> radiologique du <span class=\"kw-imagerie\">pincement</span> ; à la hanche, progression moyenne\n          <span class=\"kw-chiffre\">0,2–0,3 mm/an</span>, avec grandes variations individuelles.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> par <span class=\"kw-clinique\">poussées</span> et <span class=\"kw-clinique\">accalmies</span> ;\n          un <span class=\"kw-alerte\">épanchement chronique</span> = facteur de <span class=\"kw-alerte\">mauvais pronostic</span>.</li>\n      </ul>","frequence":0,"liens":[{"href":"https://sfr.larhumatologie.fr/sites/sfr.larhumatologie.fr/files/medias/formations-ressources/boite_outils/lequesne.pdf","label":"Indice fonctionnel de Lequesne (PDF)"}]},{"id":"129-17","rang":"B","rubrique":"Examens complémentaires","titre":"Savoir interpréter les résultats sanguins et analyse du liquide articulaire de l’arthrose","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Résultat attendu dans l'arthrose</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Biologie sanguine</strong></td>\n            <td><strong>Aucun</strong> <span class=\"kw-bio\">syndrome inflammatoire</span>\n              (<span class=\"kw-bio\">VS</span> et <span class=\"kw-bio\">CRP</span> normales) — aucun test n'est nécessaire au diagnostic</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Liquide synovial</span></strong> (si <span class=\"kw-ttt\">ponction</span>)</td>\n            <td>Liquide de type <strong><span class=\"kw-bio\">« mécanique »</span></strong> :\n              <span class=\"kw-bio\">clair</span>, <span class=\"kw-bio\">visqueux</span>,\n              <span class=\"kw-chiffre\">&lt; 2000 éléments/mm³</span>, à <span class=\"kw-bio\">prédominance mononucléée</span>,\n              <strong><span class=\"kw-bio\">sans microcristaux</span></strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">La <span class=\"kw-clinique\">ponction articulaire</span> est <strong>inutile</strong> dans une arthrose typique. Elle n'est réalisée qu'en cas de <span class=\"kw-alerte\">doute diagnostique</span> : elle élimine une <span class=\"kw-alerte\">arthrite septique</span> ou <span class=\"kw-alerte\">microcristalline</span> (liquide <span class=\"kw-etio\">inflammatoire</span>, présence de cristaux).</div>","frequence":0},{"id":"129-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une arthropathie destructrice rapide : coxarthrose, gonarthrose","contenu":"<p>La <strong>coxarthrose/gonarthrose destructrice rapide (CDR/GDR)</strong> est une forme particulière définie par\n        une chondrolyse accélérée : <strong><span class=\"kw-imagerie\">pincement &gt; 50 %</span> de l'interligne</strong> (ou\n        <span class=\"kw-imagerie\">≥ 2 mm</span>) en <span class=\"kw-chiffre\">≤ 1 an</span>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-etio\">Femme âgée (≈ 65 ans)</span>, <span class=\"kw-etio\">obèse</span> ;\n              facteurs déclenchants : traumatisme, surmenage physique</td></tr>\n          <tr><td><strong>Clinique</strong></td>\n            <td>Douleur de <span class=\"kw-alerte\">début brutal</span>, très <span class=\"kw-alerte\">intense</span>, à\n              <span class=\"kw-alerte\">recrudescence nocturne</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie</span></strong></td>\n            <td>Clichés <strong>répétés à <span class=\"kw-chiffre\">≥ 3 mois</span></strong> pour objectiver la chondrolyse ;\n              <span class=\"kw-alerte\">pas d'ostéophytose</span> (signe négatif clé ⭐) ; risque d'<span class=\"kw-alerte\">ostéolyse de la tête fémorale</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Ponction</span></strong></td>\n            <td><strong>Nécessaire en cas de doute</strong> : éliminer une <span class=\"kw-alerte\">coxite septique</span>\n              ou <span class=\"kw-alerte\">microcristalline</span> ; à la GDR, rechercher une <span class=\"kw-etio\">chondrocalcinose</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Le traitement est le plus souvent <strong>chirurgical</strong>.</div>","frequence":0},{"id":"129-19","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une arthrose digitale érosive","contenu":"<p>Forme <strong>destructrice</strong> de l'arthrose digitale, définie par la présence d'<span class=\"kw-imagerie\">érosions</span>\n        à la <span class=\"kw-imagerie\">radiographie</span> des mains. Correspond à des <span class=\"kw-clinique\">poussées congestives</span> des doigts.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong></td>\n            <td>Forme plus sévère : <span class=\"kw-clinique\">douleurs intenses</span>, horaire\n              <span class=\"kw-alerte\">mixte (mécanique + inflammatoire avec réveil nocturne)</span>, évoluant sur plusieurs semaines ;\n              <span class=\"kw-clinique\">synovites des IPP/IPD</span></td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographie (mains de face)</span></strong></td>\n            <td><span class=\"kw-imagerie\">Géodes</span> ; <span class=\"kw-imagerie\">pincement total</span> de l'interligne avec aspect en\n              <span class=\"kw-imagerie\">« aile de mouette »</span> ; <span class=\"kw-imagerie\">destruction de la plaque osseuse sous-chondrale</span> =\n              équivalent d'<span class=\"kw-imagerie\">érosion</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong></td>\n            <td><span class=\"kw-etio\">Rhumatisme psoriasique</span> (atteinte <span class=\"kw-clinique\">IPD</span>) — le\n              <span class=\"kw-imagerie\">pincement généralisé</span> oriente vers l'arthrose érosive (<span class=\"kw-bio\">vs</span> élargissement érosif du <span class=\"kw-clinique\">psoriasis</span>)</td></tr>\n        </tbody>\n      </table>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/osteoarthritis-of-the-hand","label":"Radiopaedia : Osteoarthritis of the hand"}]},{"id":"129-20","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une coxarthrose et une gonarthrose secondaire","contenu":"<table >\n        <thead><tr><th>Localisation</th><th>Étiologies secondaires & diagnostic</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coxarthrose secondaire</strong></td>\n            <td><span class=\"kw-etio\">Dysplasie de hanche</span> = <strong><span class=\"kw-chiffre\">50 %</span></strong> des coxarthroses, à rechercher\n              systématiquement par <span class=\"kw-imagerie\">coxométrie</span><br>\n              Autres : <span class=\"kw-etio\">fracture du cotyle</span>, <span class=\"kw-etio\">ostéonécrose</span>,\n              <span class=\"kw-etio\">coxites</span> (<span class=\"kw-clinique\">PR</span>, spondyloarthrite, microcristalline, septique),\n              <span class=\"kw-etio\">Paget</span></td></tr>\n          <tr><td><strong>Coxométrie normale</strong></td>\n            <td><span class=\"kw-chiffre\">CC'D &lt; 135°</span> ; <span class=\"kw-chiffre\">VCE &gt; 25°</span> ;\n              <span class=\"kw-chiffre\">VCA &gt; 25°</span> ; <span class=\"kw-chiffre\">HTE &lt; 10°</span><br>\n              <span class=\"kw-imagerie\">Coxa valga</span> (CC'D &gt; 135°, VCE &lt; 25°) ;\n              <span class=\"kw-imagerie\">coxa vara</span> (CC'D &lt; 125°)</td></tr>\n          <tr><td><strong>Gonarthrose secondaire</strong></td>\n            <td>Une atteinte <strong><span class=\"kw-imagerie\">tricompartimentale</span></strong> (ou bicompartimentale) doit faire\n              évoquer une cause secondaire : <span class=\"kw-etio\">arthrite chronique</span> (<span class=\"kw-clinique\">PR</span>, spondyloarthrite, septique,\n              microcristalline), <span class=\"kw-etio\">ostéonécrose</span> évoluée, <span class=\"kw-etio\">Paget</span></td></tr>\n        </tbody>\n      </table>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/developmental-dysplasia-of-the-hip","label":"Radiopaedia : Developmental dysplasia of the hip"},{"href":"https://radiopaedia.org/articles/acetabular-dysplasia","label":"Radiopaedia : Acetabular dysplasia"}]},{"id":"129-21","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la coxarthrose, gonarthrose et arthrose digitale","contenu":"<p>Prise en charge <strong>pluridisciplinaire</strong>, associant mesures non pharmacologiques, traitements\n        pharmacologiques et, en dernier recours, <span class=\"kw-ttt\">chirurgie</span>. Objectif : <strong>antalgie + fonction</strong> (pas de\n        traitement curatif du cartilage).</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Moyens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Non pharmacologique</strong> (socle)</td>\n            <td><span class=\"kw-clinique\">Éducation</span> + ménagement articulaire lors des poussées<br>\n              <span class=\"kw-clinique\">Activité physique</span> adaptée (marche, vélo, piscine) <strong>en dehors des poussées</strong><br>\n              <span class=\"kw-clinique\">Perte de poids</span> si surpoids/<span class=\"kw-etio\">obésité</span><br>\n              <span class=\"kw-ttt\">Canne controlatérale</span> ⭐ ; <span class=\"kw-ttt\">kinésithérapie</span> ;\n              <span class=\"kw-ttt\">orthèses</span> (semelles au genou, orthèse digitale) ; cure thermale</td></tr>\n          <tr><td><strong>Pharmacologique</strong></td>\n            <td><span class=\"kw-ttt\">Paracétamol</span> (palier I, jusqu'à <span class=\"kw-chiffre\">3 g/j</span>, à la demande)<br>\n              <span class=\"kw-ttt\">AINS</span> per os en <strong>cure courte</strong>, dose minimale efficace —\n              <span class=\"kw-ci\">contre-indiqués après 75 ans</span><br>\n              <span class=\"kw-ttt\">AINS topiques</span> au genou et aux doigts (<strong>pas</strong> à la hanche)<br>\n              <span class=\"kw-ttt\">Antalgiques de palier II</span> (<span class=\"kw-ttt\">codéine</span>, <span class=\"kw-ttt\">tramadol</span>), palier III exceptionnel<br>\n              <span class=\"kw-ttt\">Infiltration intra-articulaire de corticoïdes</span> si échec / épanchement</td></tr>\n          <tr><td><strong>Non recommandés</strong></td>\n            <td><span class=\"kw-ci\">Anti-arthrosiques d'action lente</span> et\n              <span class=\"kw-ci\">acide hyaluronique</span> : efficacité non démontrée, déremboursés</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Chirurgie</span></strong> — indiquée si arthrose symptomatique avec retentissement important <strong>malgré un\n        traitement médical bien conduit</strong> (Lequesne <span class=\"kw-chiffre\">≥ 10–12</span>) :</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Options chirurgicales</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Coxarthrose</strong></td>\n            <td><span class=\"kw-ttt\">Prothèse totale de hanche (PTH)</span> : reprise de la marche dès\n              <span class=\"kw-chiffre\">J1</span>, durée de vie <span class=\"kw-chiffre\">≈ 20 ans</span></td></tr>\n          <tr><td><strong>Gonarthrose</strong></td>\n            <td><span class=\"kw-ttt\">Prothèse totale</span> ou <span class=\"kw-ttt\">unicompartimentale</span> de genou\n              (rééducation ≈<span class=\"kw-chiffre\"> 6 semaines</span>) ; <span class=\"kw-ttt\">ostéotomie de réaxation</span> chez le sujet\n              &lt;<span class=\"kw-chiffre\"> 65 ans</span> (valgisation si genu varum) ; <span class=\"kw-ttt\">lavage articulaire</span> (option limitée)</td></tr>\n          <tr><td><strong>Arthrose digitale</strong></td>\n            <td><strong>Exceptionnelle</strong> : arthrodèse / prothèse des <span class=\"kw-ttt\">IPP</span> ;\n              trapézectomie ou prothèse trapézo-métacarpienne pour la rhizarthrose</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ L'<strong>imagerie seule ne pose jamais l'indication chirurgicale</strong> (dissociation anatomo-clinique). Complications de <span class=\"kw-bio\">PTH</span> : <span class=\"kw-alerte\">luxation</span>, <span class=\"kw-alerte\">descellement</span> (précoce → rechercher une <span class=\"kw-alerte\">infection</span> ; tardif = mécanique), <span class=\"kw-alerte\">infection</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-clinique\">Polyarthrite rhumatoïde</span> · 198 — Arthropathie microcristalline · 200 — Douleur/épanchement articulaire - Arthrite récente</em></p>","frequence":5},{"id":"129-22","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une arthrose de l’épaule","contenu":"<p>L'<span class=\"kw-def\">omarthrose</span> est l'arthrose de l'<strong><span class=\"kw-def\">articulation scapulo-humérale</span></strong>\n        (<span class=\"kw-def\">gléno-humérale</span>). Deux formes à distinguer :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Omarthrose excentrée</strong> (plus fréquente)</td>\n            <td><span class=\"kw-imagerie\">Ascension de la tête humérale</span> (n'est plus en face de la glène) ;\n              secondaire à une <span class=\"kw-etio\">rupture de la coiffe des rotateurs</span></td></tr>\n          <tr><td><strong>Omarthrose centrée</strong> (plus rare)</td>\n            <td>Tête humérale <span class=\"kw-imagerie\">centrée</span> ; primitive ou secondaire — rechercher\n              <span class=\"kw-etio\">PR</span> ou <span class=\"kw-etio\">chondrocalcinose</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Clinique</strong> : <span class=\"kw-clinique\">douleur mécanique de l'épaule</span>, <span class=\"kw-clinique\">raideur</span>.</li>\n        <li><strong>Imagerie</strong> : clichés des <span class=\"kw-imagerie\">2 épaules</span> (face 3 rotations + profil) →\n          <span class=\"kw-imagerie\">pincement</span>, <span class=\"kw-imagerie\">ostéophytes</span>, <span class=\"kw-imagerie\">géodes</span>,\n          <span class=\"kw-imagerie\">ostéocondensation</span> ; préciser <strong>centrée</strong> <span class=\"kw-bio\">vs</span> <strong>excentrée</strong>\n          (<span class=\"kw-imagerie\">ascension</span> ou non de la tête).</li>\n        <li><strong>DD</strong> : <span class=\"kw-etio\">tendinopathie</span> de la coiffe (calcifications d'insertion).</li>\n      </ul>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/osteoarthritis-of-the-shoulder","label":"Radiopaedia : Osteoarthritis of the shoulder"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> pathologie <span class=\"kw-def\">chronique</span>, pas d'<span class=\"kw-alerte\">urgence</span> vitale propre<br><strong>Drapeau :</strong> douleur d'allure <span class=\"kw-alerte\">inflammatoire, de début brutal ou fébrile</span> → éliminer une <span class=\"kw-etio\">arthrite septique</span> ou <span class=\"kw-etio\">microcristalline</span><br><strong>1er geste :</strong> <span class=\"kw-ttt\">ponction articulaire</span> avec analyse du liquide synovial si doute diagnostique<br><strong>Forme rapide :</strong> <span class=\"kw-etio\">coxarthrose / gonarthrose destructrice rapide</span> = pincement <span class=\"kw-chiffre\">> 50%</span> ou <span class=\"kw-chiffre\">2 mm</span> en <span class=\"kw-chiffre\">1 an</span></p>","hospit":"<p><strong>Ambulatoire :</strong> prise en charge en <span class=\"kw-ttt\">ville</span>, <span class=\"kw-ttt\">masso-kinésithérapie</span> en séances individuelles ambulatoires<br><strong>Avis rhumatologique :</strong> formes secondaires, doute diagnostique, gestes d'<span class=\"kw-ttt\">infiltration</span><br><strong>Avis chirurgical :</strong> orthopédiste en cas d'échec du traitement médical bien conduit<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> réservée à la <span class=\"kw-ttt\">chirurgie prothétique</span> (reprise de marche dès <span class=\"kw-chiffre\">J1</span> après <span class=\"kw-bio\">PTH</span>, rééducation <span class=\"kw-chiffre\">~6 semaines</span> après PTG)<br><strong>Sujet âgé :</strong> <span class=\"kw-def\">discussion collégiale</span> rhumatologue / orthopédiste / anesthésiste avant la <span class=\"kw-ttt\">chirurgie</span></p>","redflags":"<ul><li>Douleur de début <span class=\"kw-alerte\">brutal</span>, très <span class=\"kw-clinique\">intense</span>, à <span class=\"kw-alerte\">recrudescence nocturne</span> → <span class=\"kw-etio\">coxarthrose / gonarthrose destructrice rapide</span></li><li>Douleur d'horaire <span class=\"kw-alerte\">inflammatoire</span> avec <span class=\"kw-clinique\">réveil nocturne</span> → <span class=\"kw-etio\">rhumatisme inflammatoire</span> ou <span class=\"kw-etio\">arthrite microcristalline</span></li><li><span class=\"kw-alerte\">Fièvre</span> ou <span class=\"kw-clinique\">épanchement inflammatoire</span> (articulation chaude) → éliminer une <span class=\"kw-etio\">arthrite septique</span></li><li>Aggravation <span class=\"kw-alerte\">rapide</span> du <span class=\"kw-radio\">pincement articulaire</span> (<span class=\"kw-chiffre\">> 50% en 1 an</span>) → forme destructrice rapide, jusqu'à l'<span class=\"kw-radio\">ostéolyse de la tête fémorale</span></li><li><span class=\"kw-clinique\">Épanchement</span> chronique ou récidivant du genou → facteur de mauvais <span class=\"kw-def\">pronostic</span>, rechercher une <span class=\"kw-etio\">chondrocalcinose</span></li><li>Localisation atypique (<span class=\"kw-etio\">omarthrose</span>, <span class=\"kw-etio\">arthrose de cheville</span>) → toujours rechercher une <span class=\"kw-etio\">cause secondaire</span></li><li>Sujet âgé : l'arthrose est un facteur de <span class=\"kw-alerte\">chute</span> et de <span class=\"kw-alerte\">perte d'autonomie</span> à rechercher systématiquement</li></ul>","principes":"<p>Prise en charge <span class=\"kw-def\">pluridisciplinaire</span> et <span class=\"kw-def\">graduée</span> : mesures non pharmacologiques d'abord, puis <span class=\"kw-ttt\">antalgiques</span> et infiltrations, et <span class=\"kw-ttt\">chirurgie</span> en dernier recours.</p><p><strong>Mesures non pharmacologiques (socle)</strong></p><ul><li><span class=\"kw-ttt\">Activité physique</span> adaptée (marche, vélo, piscine) en dehors des poussées</li><li><span class=\"kw-ttt\">Perte de poids</span> si surpoids/<span class=\"kw-etio\">obésité</span> + conseils diététiques systématiques</li><li><span class=\"kw-ttt\">Masso-kinésithérapie</span> : renforcement musculaire, lutte contre le <span class=\"kw-clinique\">flessum</span></li><li><span class=\"kw-ttt\">Canne controlatérale</span> lors des poussées (coxarthrose)</li><li><span class=\"kw-ttt\">Orthèses plantaires</span> / semelles amortissantes (genou), <span class=\"kw-ttt\">orthèse digitale</span> de repos (mains)</li><li><span class=\"kw-ttt\">Cure thermale</span> si polyarthrose ou <span class=\"kw-def\">comorbidités</span> limitant <span class=\"kw-clinique\">les</span> médicaments</li></ul><p><strong>Mesures pharmacologiques</strong></p><p>Adapter aux <span class=\"kw-def\">comorbidités</span> et à la fonction rénale, surtout chez le sujet âgé.</p><ul><li><span class=\"kw-ttt\">Paracétamol</span> (palier I) à la demande, jusqu'à <span class=\"kw-chiffre\">3 g/jour</span></li><li><span class=\"kw-ttt\">AINS</span> per os en cure courte, dose minimale efficace — <span class=\"kw-ci\">contre-indiqués après 75 ans</span></li><li><span class=\"kw-ttt\">AINS topiques</span> : gonarthrose et arthrose digitale (pas la coxarthrose)</li><li><span class=\"kw-ttt\">Antalgiques de palier II</span> (<span class=\"kw-ttt\">codéine</span>, <span class=\"kw-ttt\">tramadol</span>), exceptionnellement <span class=\"kw-ttt\">palier III</span> (<span class=\"kw-ttt\">morphine</span>)</li><li><span class=\"kw-ttt\">Infiltration intra-articulaire de corticoïdes</span> : si échec du traitement <span class=\"kw-etio\">médicamenteux</span> ou épanchement</li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> (dernier recours)</strong></p><p>Coxarthrose / gonarthrose destructrice rapide = traitement chirurgical.</p><ul><li>Hanche : <span class=\"kw-ttt\">prothèse totale de hanche (PTH)</span>, durée de vie <span class=\"kw-chiffre\">~20 ans</span></li><li>Genou : <span class=\"kw-ttt\">PTG</span>, <span class=\"kw-ttt\">prothèse unicompartimentale</span> ou <span class=\"kw-ttt\">ostéotomie de réaxation</span> (sujet <span class=\"kw-chiffre\">< 65 ans</span>)</li><li>Indication : échec du traitement médical bien conduit + retentissement majeur (<span class=\"kw-chiffre\">Lequesne ≥ 10-12</span>)</li><li><span class=\"kw-ci\">L'imagerie seule ne pose jamais l'indication chirurgicale</span> (dissociation anatomo-clinique)</li></ul><p><strong>Non recommandés</strong></p><ul><li><span class=\"kw-ttt\">Anti-arthrosiques d'action lente</span> : pas de preuve réelle d'efficacité, non remboursés</li><li><span class=\"kw-ttt\">Injections d'acide hyaluronique</span> : pas d'effet sur la dégradation du cartilage</li></ul>","suivi":"<p><strong>Clinique :</strong> <span class=\"kw-clinique\">périmètre de marche</span> et <span class=\"kw-clinique\">douleur à la marche</span> (EVA)<br><strong>Scores :</strong> indices algofonctionnels (<span class=\"kw-def\">Lequesne</span>, <span class=\"kw-def\">WOMAC</span>) et qualité de vie<br><strong>Genou :</strong> régression de l'<span class=\"kw-clinique\">épanchement</span> s'il était présent initialement<br><strong>Forme destructrice rapide :</strong> répéter <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">radiographies</span> à <span class=\"kw-chiffre\">≥ 3 mois</span> d'intervalle pour suivre la chondrolyse</p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-8-0.php","label":"Collège (COFER) — cours Arthrose"},{"href":"https://radiopaedia.org/articles/osteoarthritis","label":"Radiopaedia : Osteoarthritis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur articulaire d'horaire mécanique (hanche / genou / doigts) — Calmée par le repos, dérouillage matinal < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>15</span> min</span>, sans <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span>","detail":"<h4>CAT — Arthrose : diagnostic et stratégie thérapeutique — Douleur articulaire mécanique : confirmer l'arthrose, écarter <span class=\"kw-clinique\">les</span> pièges, puis traiter par paliers</h4>","branches":[{"to":"q-typique","label":"Suspicion d'arthrose","color":"blue"}]},{"id":"q-typique","kind":"decision","label":"Tableau clinico-radiographique typique d'arthrose ? — Douleur mécanique + signes cardinaux en radiographie (pincement localisé, ostéophytose, géodes, ostéosclérose) — aucune biologie nécessaire","branches":[{"to":"t-bilan","label":"Non — atypique / inflammatoire","color":"amber"},{"to":"q-reponse","label":"Oui — mécanique + RX typique","color":"green"}]},{"id":"t-bilan","kind":"terminal","label":"Compléter le bilan avant de retenir l'arthrose — Présentation atypique → éliminer un diagnostic différentiel","color":"amber","detail":"<h4>Si <span class=\"kw-clinique\">fièvre</span> / épanchement <span class=\"kw-etio\">inflammatoire</span></h4><ul><li><span class=\"kw-ttt\">Ponction articulaire</span> : éliminer une <span class=\"kw-etio\">arthrite septique</span> ou <span class=\"kw-etio\">microcristalline</span></li></ul><h4>Si douleur brutale / aggravation rapide</h4><ul><li><span class=\"kw-imagerie\">IRM</span> : <span class=\"kw-etio\">ostéonécrose</span>, <span class=\"kw-etio\">fissure de contrainte</span>, <span class=\"kw-etio\">atteinte méniscale</span></li><li>Répéter <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">radiographies</span> à <span class=\"kw-chiffre\">≥ 3 mois</span> si suspicion de <span class=\"kw-etio\">destruction rapide</span></li></ul><h4>Conduite</h4><ul><li>Localisation atypique (<span class=\"kw-etio\">omarthrose</span>, <span class=\"kw-etio\">arthrose de cheville</span>) → rechercher une <span class=\"kw-etio\">cause secondaire</span></li></ul>"},{"id":"q-reponse","kind":"decision","label":"Soulagement par le traitement médical bien conduit ? — Mesures non pharmacologiques + antalgiques / AINS","branches":[{"to":"t-ambu","label":"Oui — soulagé","color":"green"},{"to":"q-chir","label":"Non — échec","color":"amber"}]},{"id":"t-ambu","kind":"terminal","label":"Poursuite du traitement médical + suivi ambulatoire — Arthrose contrôlée","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Mesures de ménagement articulaire</span> + <span class=\"kw-ttt\">activité physique</span> adaptée</li><li><span class=\"kw-ttt\">Paracétamol</span> à la demande, <span class=\"kw-ttt\">AINS</span> en cure courte si besoin</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Périmètre de marche</span>, douleur (EVA), indices de <span class=\"kw-def\">Lequesne</span> / <span class=\"kw-def\">WOMAC</span></li></ul>"},{"id":"q-chir","kind":"decision","label":"Retentissement majeur + Lequesne ≥ 10-12 ? — Après échec d'un traitement médical bien conduit","branches":[{"to":"t-optim","label":"Non","color":"amber"},{"to":"t-chir","label":"Oui","color":"red"}]},{"id":"t-optim","kind":"terminal","label":"Optimiser le traitement médical — Avant d'envisager la chirurgie","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Infiltration intra-articulaire de corticoïdes</span></li><li>Renforcer la <span class=\"kw-ttt\">masso-kinésithérapie</span></li><li><span class=\"kw-ttt\">Antalgiques de palier II</span> si nécessaire</li></ul>"},{"id":"t-chir","kind":"terminal","label":"Chirurgie après discussion collégiale — Orthopédiste — hospitalisation","color":"red","detail":"<h4>Traitement</h4><ul><li>Hanche : <span class=\"kw-ttt\">prothèse totale de hanche</span> (reprise de marche <span class=\"kw-chiffre\">J1</span>)</li><li>Genou : <span class=\"kw-ttt\">PTG</span>, <span class=\"kw-ttt\">prothèse unicompartimentale</span> ou <span class=\"kw-ttt\">ostéotomie de réaxation</span> (<span class=\"kw-chiffre\">< 65 ans</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ci\">L'imagerie seule ne pose pas l'indication</span> (dissociation anatomo-clinique)</li><li>Discussion <span class=\"kw-def\">rhumatologue / orthopédiste / anesthésiste</span> chez le sujet âgé</li></ul>"}]},"cards":[{"i":"1391fa8060f2","n":129,"o":"129-1","u":"Définition","t":"Connaître la définition générale de l’arthrose, les principales localisations","q":"Quelles sont les principales localisations préférentielles de l'arthrose ?","a":"<ul><li>Le <strong>rachis</strong> et les <strong>genoux</strong> (gonarthrose)</li><li>Les <strong>mains</strong></li><li>Les <strong>hanches</strong> (coxarthrose)</li></ul>"},{"i":"9742f041f063","n":129,"o":"129-1","u":"Définition","t":"Connaître la définition générale de l’arthrose, les principales localisations","q":"Quelles sont les principales caractéristiques de la présentation clinique de l'arthrose ?","a":"<p>L'arthrose est longtemps <strong>asymptomatique</strong> avant de devenir symptomatique. Elle se manifeste alors principalement par une <strong>douleur mécanique</strong> et une <strong>gêne fonctionnelle</strong>.</p>"},{"i":"ac5de8ac214f","n":129,"o":"129-1","u":"Définition","t":"Connaître la définition générale de l’arthrose, les principales localisations","q":"Quelle est la définition générale de l'arthrose ?","a":"<p>L'arthrose est une <strong>maladie articulaire</strong> caractérisée par une <strong>destruction du cartilage</strong> articulaire, s'étendant secondairement à toutes les structures de l'articulation comme la membrane synoviale et l'os sous-chondral. C'est la <strong>maladie rhumatismale la plus fréquente</strong>.</p>"},{"i":"2196b365532d","n":129,"o":"129-10","u":"Examens complémentaires","t":"Connaître la sémiologie générale en radio de l’arthrose : coxarthrose gonarthrose, arthrose digitale","q":"Quels sont les signes radiologiques 'négatifs' attendus dans l'arthrose qui la différencient des rhumatismes inflammatoires ?","a":"<p>Dans l'arthrose, les signes radiologiques 'négatifs' attendus incluent l'<strong>absence de déminéralisation</strong> et l'<strong>absence d'érosion ou de destruction articulaire</strong> (sauf dans les formes digitales érosives). Ces absences la distinguent des rhumatismes inflammatoires.</p>"},{"i":"a37e6b11b94f","n":129,"o":"129-10","u":"Examens complémentaires","t":"Connaître la sémiologie générale en radio de l’arthrose : coxarthrose gonarthrose, arthrose digitale","q":"Quel est le signe radiologique le plus spécifique de l'arthrose et comment se manifeste-t-il ?","a":"<p>Le signe radiologique le plus spécifique de l'arthrose est l'<strong>ostéophytose marginale</strong>, qui se manifeste par des <strong>becs osseux</strong> aux marges articulaires.</p>"},{"i":"ae052ea9280a","n":129,"o":"129-10","u":"Examens complémentaires","t":"Connaître la sémiologie générale en radio de l’arthrose : coxarthrose gonarthrose, arthrose digitale","q":"Comment se caractérise le pincement de l'interligne articulaire dans l'arthrose à la radiographie ?","a":"<p>Dans l'arthrose, le pincement de l'interligne articulaire est <strong>localisé</strong>, typiquement à la zone d'hyperpression. Il est apprécié de façon comparative et se distingue d'un pincement global observé dans les arthrites inflammatoires.</p>"},{"i":"db5ca378a28a","n":129,"o":"129-10","u":"Examens complémentaires","t":"Connaître la sémiologie générale en radio de l’arthrose : coxarthrose gonarthrose, arthrose digitale","q":"Quels sont les quatre signes radiologiques cardinaux de l'arthrose ?","a":"Les quatre signes radiologiques cardinaux de l'arthrose sont :\n<ul>\n<li>Le <strong>pincement de l'interligne articulaire</strong>.</li>\n<li>L'<strong>ostéophytose marginale</strong>.</li>\n<li>Les <strong>géodes sous-chondrales</strong>.</li>\n<li>L'<strong>ostéosclérose (ou condensation) sous-chondrale</strong>.</li>\n</ul>"},{"i":"fb05a995bab7","n":129,"o":"129-10","u":"Examens complémentaires","t":"Connaître la sémiologie générale en radio de l’arthrose : coxarthrose gonarthrose, arthrose digitale","q":"Que sont les géodes sous-chondrales et l'ostéosclérose sous-chondrale dans le contexte de l'arthrose à la radiographie ?","a":"<ul>\n<li>Les <strong>géodes sous-chondrales</strong> sont des <strong>lacunes cerclées</strong>, visibles en regard du pincement maximal dans la zone d'hyperpression.</li>\n<li>L'<strong>ostéosclérose sous-chondrale</strong> correspond à une <strong>densification osseuse</strong> aux mêmes zones d'hyperpression articulaire.</li>\n</ul>"},{"i":"c946da46d2df","n":129,"o":"129-11","u":"Contenu multimédia","t":"Radiographie de coxarthrose","q":"Pourquoi la réalisation d'un cliché de profil (faux profil de Lequesne) est-elle importante dans le diagnostic radiologique de la coxarthrose ?","a":"<p>La réalisation d'un cliché de profil, tel que le <strong>faux profil de Lequesne</strong>, est importante car il peut révéler un <strong>pincement articulaire antérieur</strong> qui pourrait ne pas être visible sur le cliché de face. Cela augmente la sensibilité du diagnostic radiologique de la coxarthrose.</p>"},{"i":"d7fa1822d7d0","n":129,"o":"129-11","u":"Contenu multimédia","t":"Radiographie de coxarthrose","q":"Quels sont les signes radiographiques caractéristiques de la coxarthrose sur un bassin de face et un faux profil de Lequesne ?","a":"<p>Les signes radiographiques de la coxarthrose sont :</p><ul><li>Un <strong>pincement articulaire</strong>, le plus souvent <strong>supéro-latéral</strong> de l'interligne sur le bassin de face.</li><li>Une <strong>ostéosclérose condensante</strong>, localisée au pôle supérieur de la tête fémorale et au toit du cotyle.</li><li>Des <strong>ostéophytes marginaux</strong> (avant-toit, péri-céphaliques, péri-fovéaux, « en hamac » sous le col).</li><li>Des <strong>géodes</strong>, situées dans les zones d'hyperpression.</li><li>À un stade évolué, une <strong>perte de sphéricité de la tête fémorale</strong>.</li></ul>"},{"i":"1e9c98c5a84d","n":129,"o":"129-12","u":"Contenu multimédia","t":"Radiographie de gonarthrose","q":"Existe-t-il une corrélation entre les lésions radiologiques et la clinique dans la gonarthrose ?","a":"<p>Non, il n'y a <strong>pas de corrélation</strong> systématique entre l'importance des lésions radiologiques de la gonarthrose et la symptomatologie clinique du patient.</p>"},{"i":"2205231ccddf","n":129,"o":"129-12","u":"Contenu multimédia","t":"Radiographie de gonarthrose","q":"Quels sont les signes radiologiques caractéristiques d'une gonarthrose ?","a":"<ul><li><strong>Pincement localisé de l'interligne</strong> articulaire (le plus souvent dans un seul compartiment fémoro-tibial, notamment médial).</li><li><strong>Ostéophytose marginale</strong> (interne et externe) et des épines tibiales.</li><li><strong>Géodes</strong> sous-chondrales.</li><li><strong>Ostéosclérose sous-chondrale</strong>.</li></ul>"},{"i":"404a4cd343e7","n":129,"o":"129-12","u":"Contenu multimédia","t":"Radiographie de gonarthrose","q":"Quel est l'intérêt de la radiographie du genou en incidence de schuss dans l'exploration de la gonarthrose ?","a":"<p>L'incidence de schuss est réalisée en <strong>charge avec 30° de flexion</strong>. Elle permet d'explorer le <strong>compartiment postérieur</strong> du genou, souvent le plus précocement atteint, et de révéler un pincement qui ne serait pas visible sur un cliché en extension.</p>"},{"i":"6fca7a8f8bab","n":129,"o":"129-12","u":"Contenu multimédia","t":"Radiographie de gonarthrose","q":"Quelle incidence radiographique est le cliché de référence dans l'évaluation d'une gonarthrose ?","a":"<p>L'incidence de référence pour l'évaluation de la gonarthrose est la radiographie du genou de <strong>face en incidence de schuss</strong>.</p>"},{"i":"77328bfd084d","n":129,"o":"129-13","u":"Contenu multimédia","t":"Radiographie d’arthrose des articulations interphalangiennes distales","q":"Quel signe clinique correspond aux ostéophytes exubérants observés à la radiographie de l'arthrose digitale des interphalangiennes distales ?","a":"Les ostéophytes exubérants observés à la radiographie de l'arthrose digitale des interphalangiennes distales (IPD) correspondent cliniquement aux <strong>nodosités d'Heberden</strong>."},{"i":"b3010d18bcf0","n":129,"o":"129-13","u":"Contenu multimédia","t":"Radiographie d’arthrose des articulations interphalangiennes distales","q":"Quels sont les signes radiographiques classiquement absents dans l'arthrose des articulations interphalangiennes distales, permettant de la différencier d'autres pathologies articulaires ?","a":"Dans l'arthrose des articulations interphalangiennes distales (IPD), on note classiquement l'absence d'<strong>érosions</strong> et de <strong>destructions articulaires</strong>, sauf dans la forme particulière d'arthrose érosive."},{"i":"cc41f4ea1899","n":129,"o":"129-13","u":"Contenu multimédia","t":"Radiographie d’arthrose des articulations interphalangiennes distales","q":"Quels sont les signes radiographiques caractéristiques de l'arthrose des articulations interphalangiennes distales (IPD) ?","a":"Les signes radiographiques de l'arthrose des IPD incluent :\n<ul>\n  <li>Un <strong>pincement de l'interligne articulaire</strong>, souvent global.</li>\n  <li>Des <strong>ostéophytes latéraux / marginaux</strong>, responsables cliniquement des nodosités.</li>\n  <li>Des <strong>géodes</strong>.</li>\n  <li>Une <strong>ostéocondensation sous-chondrale</strong>.</li>\n</ul>"},{"i":"587a6d8ad375","n":129,"o":"129-15","u":"Diagnostic positif","t":"Connaître diagnostics différentiels d’arthrose","q":"Quels sont les diagnostics différentiels d'arthrose à éliminer impérativement, et comment ?","a":"<ul><li>Il faut éliminer une <strong>arthrite microcristalline</strong> (goutte, chondrocalcinose).</li><li>Il faut éliminer une <strong>arthrite septique</strong>, nécessitant une <strong>ponction articulaire</strong> au moindre doute pour diagnostic.</li></ul>"},{"i":"71d8759be927","n":129,"o":"129-15","u":"Diagnostic positif","t":"Connaître diagnostics différentiels d’arthrose","q":"Quelles sont les caractéristiques biologiques et radiologiques qui distinguent l'arthrose d'un rhumatisme inflammatoire ?","a":"<ul><li><strong>Biologiquement</strong> : l'<strong>arthrose</strong> ne présente pas de syndrome inflammatoire, alors qu'un <strong>rhumatisme inflammatoire</strong> peut en avoir un.</li><li><strong>Radiologiquement</strong> : l'<strong>arthrose</strong> se caractérise par un pincement articulaire <strong>localisé</strong> et des <strong>ostéophytes</strong> (spécifiques) sans érosion. Un <strong>rhumatisme inflammatoire</strong> présente un pincement <strong>global</strong>, des <strong>érosions</strong> et une déminéralisation osseuse.</li></ul>"},{"i":"ef110aef065c","n":129,"o":"129-15","u":"Diagnostic positif","t":"Connaître diagnostics différentiels d’arthrose","q":"Comment l'horaire de la douleur articulaire permet-il de différencier une arthrose d'un rhumatisme inflammatoire ?","a":"<p>Pour l'<strong>arthrose</strong>, la douleur est de type <strong>mécanique</strong> : elle survient à l'effort et est calmée par le repos.</p><p>Pour un <strong>rhumatisme inflammatoire</strong>, la douleur est de type <strong>inflammatoire</strong> : elle entraîne des réveils nocturnes et un dérouillage matinal prolongé.</p>"},{"i":"0e2563228c09","n":129,"o":"129-22","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une arthrose de l’épaule","q":"Quels sont les signes cliniques évocateurs d'une omarthrose ?","a":"<p>Les signes cliniques évocateurs d'une omarthrose sont une <strong>douleur mécanique de l'épaule</strong> et une <strong>raideur</strong> de l'articulation.</p>"},{"i":"0e81bb115618","n":129,"o":"129-22","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une arthrose de l’épaule","q":"Quels sont les examens d'imagerie clés pour le diagnostic de l'omarthrose et quels signes radiologiques recherchez-vous ?","a":"<p>L'imagerie repose sur des <strong>radiographies des deux épaules</strong> (face avec 3 rotations + profil). Les signes radiologiques à rechercher sont :</p><ul><li>Un <strong>pincement</strong> de l'interligne articulaire.</li><li>La présence d'<strong>ostéophytes</strong>.</li><li>Des <strong>géodes</strong>.</li><li>Une <strong>ostéocondensation</strong>.</ul><p>Il est également essentiel de préciser s'il s'agit d'une forme <strong>centrée ou excentrée</strong> par la recherche d'une ascension de la tête humérale.</p>"},{"i":"5e2ca32fda3b","n":129,"o":"129-22","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une arthrose de l’épaule","q":"Comment définir l'omarthrose et quelles sont ses deux principales formes ?","a":"<p>L'omarthrose est l'arthrose de l'<strong>articulation scapulo-humérale</strong> (gléno-humérale). Ses deux formes sont :</p><ul><li>L'<strong>omarthrose excentrée</strong> (la plus fréquente), caractérisée par une <strong>ascension de la tête humérale</strong>, secondaire à une rupture de la coiffe des rotateurs.</li><li>L'<strong>omarthrose centrée</strong> (plus rare), où la tête humérale reste centrée, primitive ou secondaire à d'autres pathologies (ex: polyarthrite rhumatoïde, chondrocalcinose).</li></ul>"},{"i":"ac86b9b8fef8","n":129,"o":"129-22","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une arthrose de l’épaule","q":"Quel est le principal diagnostic différentiel de l'omarthrose à connaître ?","a":"<p>Le principal diagnostic différentiel à connaître pour l'omarthrose est la <strong>tendinopathie de la coiffe des rotateurs</strong>, notamment lorsqu'elle présente des calcifications d'insertion.</p>"},{"i":"6ed8aa4decdc","n":129,"o":"129-5","u":"Etiologies","t":"Connaître les principaux facteurs de risque de l’arthrose","q":"Quels sont les facteurs de risque liés à un excès de contrainte mécanique pour l'arthrose ?","a":"<p>Les facteurs de risque liés à un excès de contrainte mécanique pour l'arthrose sont :</p><ul><li>Le <strong>port de charges lourdes</strong> et les <strong>microtraumatismes répétés</strong>.</li><li>Les <strong>antécédents de lésions ménisco-ligamentaires</strong> (croisés, ménisques) ou de <strong>fractures articulaires</strong>.</li><li>Les <strong>troubles d'architecture</strong>, comme le <strong>genu varum</strong> ou le <strong>genu valgum</strong> au niveau du genou, ou la <strong>dysplasie de hanche</strong>.</li></ul>"},{"i":"706323da4113","n":129,"o":"129-5","u":"Etiologies","t":"Connaître les principaux facteurs de risque de l’arthrose","q":"Quels sont les facteurs de risque métaboliques de l'arthrose ?","a":"<p>Les facteurs de risque métaboliques de l'arthrose sont :</p><ul><li>Le <strong>surpoids / obésité</strong>, favorisant les articulations portantes (genou, rachis, hanche) et non portantes (digitale).</li><li>Le <strong>syndrome métabolique</strong> (HTA, DT2/insulinorésistance, dyslipidémie, obésité).</li></ul>"},{"i":"7f2f5d95e8e9","n":129,"o":"129-5","u":"Etiologies","t":"Connaître les principaux facteurs de risque de l’arthrose","q":"Quels sont les facteurs de risque non modifiables de l'arthrose ?","a":"<p>Les facteurs de risque non modifiables de l'arthrose sont :</p><ul><li>L'<strong>âge</strong> : rare avant <strong>40 ans</strong>, forte incidence après <strong>60 ans</strong>.</li><li>Le <strong>sexe féminin</strong>, surtout après la <strong>ménopause</strong>.</li><li>L'<strong>hérédité</strong> (polymorphismes de susceptibilité), impliquant principalement l'<strong>arthrose digitale</strong>.</li></ul>"},{"i":"4f04fae9fa0b","n":129,"o":"129-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des principales localisations arthrosiques : coxarthrose, gonarthrose, arthrose digitale","q":"Quels sont les principaux diagnostics différentiels à évoquer devant une douleur de hanche faisant suspecter une coxarthrose ?","a":"<p>Devant une douleur de hanche suspecte de coxarthrose, il faut évoquer :</p><ul><li>Une <strong>cruralgie</strong> (rechercher un déficit neurologique, un réflexe rotulien aboli).</li><li>Une <strong>ostéonécrose de la tête fémorale</strong> (contexte d'<strong>alcoolisme</strong>, de prise de <strong>corticoïdes</strong> ; diagnostic par <strong>IRM</strong>).</li><li>Une <strong>fissure ostéoporotique du bassin</strong>.</li><li>Un <strong>syndrome douloureux régional complexe (SDRC) de hanche</strong> (notamment chez la femme enceinte).</li><li>Une <strong>tendinopathie</strong> du moyen fessier ou du droit antérieur.</li><li>Une <strong>névralgie fémoro-cutanée</strong>.</li></ul>"},{"i":"f5487281e3e0","n":129,"o":"129-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des principales localisations arthrosiques : coxarthrose, gonarthrose, arthrose digitale","q":"Quels sont les diagnostics différentiels des atteintes articulaires digitales qui peuvent simuler une arthrose digitale ?","a":"<p>Face à une atteinte articulaire digitale simulant une arthrose, il faut envisager :</p><ul><li>Un <strong>rhumatisme psoriasique</strong> (qui atteint aussi les <strong>articulations interphalangiennes distales - IPD</strong>, mais avec érosions et élargissement).</li><li>Une <strong>polyarthrite rhumatoïde</strong>.</li><li>Une <strong>goutte</strong> (ne pas confondre les tophus avec les nodosités d'Heberden ou de Bouchard classiques de l'arthrose).</li><li>Une <strong>chondrocalcinose</strong>.</li></ul>"},{"i":"f8ff6d7738c9","n":129,"o":"129-8","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels des principales localisations arthrosiques : coxarthrose, gonarthrose, arthrose digitale","q":"Quels sont les principaux diagnostics différentiels à considérer face à une douleur du genou simulant une gonarthrose ?","a":"<p>Pour une douleur du genou, pouvant faire penser à une gonarthrose, les diagnostics différentiels incluent :</p><ul><li>Une <strong>douleur coxofémorale projetée</strong> ou une <strong>radiculalgie L3-L4</strong>.</li><li>Une <strong>lésion méniscale</strong> (notamment chez le sujet jeune, après un traumatisme, avec des blocages).</li><li>Une <strong>arthropathie microcristalline</strong>.</li><li>Une <strong>ostéonécrose</strong> ou une <strong>fissure d'un condyle</strong>.</li><li>Une <strong>phlébite</strong>.</li><li>Des <strong>tendinopathies</strong> (rotulienne, de la patte d'oie).</li></ul>"},{"i":"2d9d4f9d1d9a","n":129,"o":"129-9","u":"Examens complémentaires","t":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","q":"Quels clichés radiographiques sont indispensables pour le diagnostic d'une gonarthrose ?","a":"<ul><li><strong>Face en appui bipodal</strong> (genou en extension)</li><li><strong>Profil</strong></li><li><strong>Défilé fémoro-patellaire</strong> à 30°</li><li><strong>Incidence en schuss</strong> (face, en charge, à 30° de flexion)</li></ul>"},{"i":"3d5091bb928a","n":129,"o":"129-9","u":"Examens complémentaires","t":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","q":"Quelle est la particularité de la corrélation entre les signes radiologiques et cliniques dans l'arthrose ?","a":"<p>Il existe une <strong>dissociation anatomo-clinique</strong>, ce qui signifie que l'importance des lésions radiologiques n'est pas corrélée à la douleur ressentie par le patient ni à son retentissement fonctionnel.</p>"},{"i":"44a9e78ddd66","n":129,"o":"129-9","u":"Examens complémentaires","t":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","q":"Dans quels cas a-t-on recours à d'autres imageries (échographie, IRM, arthroscanner) dans le cadre de l'arthrose ?","a":"<p>Les autres imageries (échographie, IRM, arthroscanner) sont réservées au <strong>doute diagnostique</strong> ou pour l'exploration des <strong>diagnostics différentiels</strong> (ex: ostéonécrose, fissure, lésion du labrum) ou pour la ponction et l'analyse d'épanchement articulaire.</p>"},{"i":"b18614633c1d","n":129,"o":"129-9","u":"Examens complémentaires","t":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","q":"Quel cliché radiographique est indispensable pour le diagnostic d'une arthrose digitale ?","a":"<p>Une <strong>radiographie des mains de face</strong> est indispensable pour le diagnostic de l'arthrose digitale.</p>"},{"i":"c53a0a3434fc","n":129,"o":"129-9","u":"Examens complémentaires","t":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","q":"Quels clichés radiographiques sont indispensables pour le diagnostic d'une coxarthrose ?","a":"<ul><li><strong>Bassin debout de face</strong> (avec membres en rotation interne 20°)</li><li><strong>Faux profil de Lequesne</strong> de chaque hanche</li></ul>"},{"i":"f907b53528d6","n":129,"o":"129-9","u":"Examens complémentaires","t":"Arthrose : connaître l’indication de l’imagerie (coxarthrose, gonarthrose, arthrose digitale)","q":"Quel est l'examen d'imagerie de première intention et essentiel pour le diagnostic de l'arthrose ?","a":"<p>La <strong>radiographie standard</strong> est l'examen clé et suffit au diagnostic dans la grande majorité des cas d'arthrose. Aucun examen biologique ou imagerie en coupe n'est nécessaire en première intention.</p>"}]};